validator:
function validate(input) {
  const [{ cinema = [] }] = input;
  const ids = new Set(), reported = new Set();
  for (const [id, , description, rating] of cinema) {
    if (id === null || id < 1) return 'Every film needs a positive id.';
    if (ids.has(id)) return `id ${id} appears twice in cinema.`;
    ids.add(id);
    if (description === null || rating === null) return `Film ${id} needs a description and a rating.`;
    if (rating < 0 || rating > 10) return `rating ${rating} is outside 0 to 10.`;
    if (id % 2 === 1 && description.toLowerCase() !== 'boring') {
      if (reported.has(rating)) return `Two reported films share the rating ${rating}.`;
      reported.add(rating);
    }
  }
  return null;
}

generator:
function generate(rand, size) {
  const titles = ['War', 'Science', 'irish', 'Ice song', 'House card', 'Dune', 'Up', 'Heat'];
  const blurbs = ['boring', 'boring', 'great 3D', 'fiction', 'Fantacy', 'Interesting', 'not boring', 'boring plot'];
  const pick = list => list[Math.floor(rand() * list.length)];
  // Ratings 0.0 .. 9.9, handed out without repeats to the films that will be reported.
  const pool = Array.from({ length: 100 }, (_, i) => i / 10);
  for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  let next = 0;
  const count = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const ids = Array.from({ length: size === 'small' ? 12 : 2000 }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const cinema = [];
  for (const id of ids.slice(0, count)) {
    let description = pick(blurbs);
    // A large table keeps at most 100 reported films so their ratings stay distinct.
    if (id % 2 === 1 && description !== 'boring' && next >= pool.length) description = 'boring';
    const reported = id % 2 === 1 && description !== 'boring';
    const rating = reported ? pool[next++] : Math.floor(rand() * 100) / 10;
    cinema.push([id, pick(titles), description, rating]);
  }
  return [{ cinema }];
}
